using System.Diagnostics;

namespace MZikmund.Web.Data.Entities;

[DebuggerDisplay("{" + nameof(DisplayName) + "}")]
public class CommentAuthorEntity
{
	/// <summary>
	/// The Supabase <c>sub</c> claim. Assigned by the identity provider, never generated by the database.
	/// </summary>
	public Guid Id { get; set; }

	public string DisplayName { get; set; } = "";

	public string? AvatarUrl { get; set; }

	public string Email { get; set; } = "";

	public bool IsBanned { get; set; }

	/// <summary>
	/// Whether the author is the site owner, taken from the app_metadata role claim at each write.
	/// </summary>
	public bool IsAdmin { get; set; }

	/// <summary>
	/// Unused in v1; present so reply notifications need no migration later.
	/// </summary>
	public bool NotifyOnReply { get; set; } = true;

	public DateTime CreatedOn { get; set; }

	public DateTime LastSeenOn { get; set; }
}
